from pathlib import Path
import json,re,base64
p=Path(__file__).parent;data=json.loads((p/'chart-data.json').read_text());gsap=(p.parent/'uniland-global-25s/assets/gsap.min.js').read_text();gsap=re.sub(r'//# sourceMappingURL=.*','',gsap)
font=base64.b64encode((p.parent/'uniland-shotcraft-15s/public/fonts/brand-bold.ttf').read_bytes()).decode()
source='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>UNILAND · Animated charts preview</title><style>@font-face{font-family:Finance;src:url(data:font/ttf;base64,__FONT__)}*{box-sizing:border-box}body{margin:0;background:#080a0c;color:#f1f3f5;font-family:Finance,Arial,sans-serif;display:flex;flex-direction:column;align-items:center;padding:16px}#wrap{position:relative;overflow:hidden}#canvas{width:1080px;height:1920px;position:relative;transform-origin:top left;background:#101214;padding:80px 90px;display:flex;flex-direction:column;gap:20px}#kicker{font-size:34px;letter-spacing:4px;color:#adb9c8;border-top:2px solid #23364b;padding-top:38px}h1{font-size:72px;line-height:1.12;margin:0;letter-spacing:-2px;min-height:245px;display:flex;align-items:center}#subtitle{font-size:42px;line-height:1.4;color:#adb9c8;min-height:110px}#plot{position:relative;display:flex;flex-direction:column;gap:24px;flex:none;height:600px;justify-content:space-between}.row{height:130px;display:flex;flex-direction:column;gap:20px}.row-head{display:flex;justify-content:space-between;align-items:baseline;gap:20px}.name{font-size:48px;color:#adb9c8}.value{font-size:64px;color:#a9c9e8;font-variant-numeric:tabular-nums}.track{position:relative;width:100%;height:57px;border-bottom:1px solid #344454}.bar{position:absolute;inset:0 auto 0 0;width:0;background:#7c9ec7;transform-origin:left}.row:first-child .bar{background:#365d88}#axis{display:flex;justify-content:space-between;margin-top:15px;font-size:32px;color:#adb9c8}#unit{font-size:38px;color:#adb9c8;text-align:center;margin-top:5px}#notes{font-size:32px;line-height:1.5;color:#adb9c8;margin-top:25px;min-height:200px;flex-shrink:0}#source{font-size:28px;line-height:1.5;color:#adb9c8;margin-top:auto;flex-shrink:0;border-top:2px solid #23364b;padding-top:25px}nav{display:flex;gap:8px;flex-wrap:wrap;max-width:600px;padding:16px 0}button{background:#18222d;color:#f1f3f5;border:1px solid #344454;padding:12px;cursor:pointer}p{font:13px/1.5 Arial,sans-serif;color:#adb9c8;max-width:600px}</style><div id="wrap"><div id="canvas"><div id="kicker">UNILAND · FINANCIAL VISUALIZATION</div><h1></h1><div id="subtitle"></div><div id="plot"></div><div id="axis"></div><div id="unit"></div><div id="notes"></div><div id="source">REPORTED FIGURES · USER-PROVIDED REFERENCES<br>NOT INDEPENDENTLY VERIFIED</div></div></div><nav><button data-chart="funding">Funding</button><button data-chart="balance_sheet">Assets & liabilities</button><button data-chart="deliveries">Deliveries</button><button id="replay">Replay animation</button></nav><p>Chart motion study only: no voiceover or music. Bars enter every four beats on a122BPM grid; final film will synchronize to the actual backing track. Values and approximate/lower-bound qualifiers are preserved. Landscape reference reflowed for portrait readability.</p><script>__GSAP__</script><script>const DATA=__DATA__;let active='funding',tl;function show(key){active=key;const d=DATA[key];if(tl)tl.kill();document.querySelector('h1').textContent=d.title;document.getElementById('subtitle').textContent=d.subtitle;document.getElementById('unit').textContent=d.unit;document.getElementById('notes').textContent=d.notes.join(' ');document.getElementById('plot').innerHTML=d.series.map((r,i)=>'<div class="row"><div class="row-head"><span class="name">'+r.name+'</span><span class="value" id="v'+i+'"></span></div><div class="track"><div class="bar" id="b'+i+'"></div></div></div>').join('');const ticks=[];for(let v=0;v<=d.axis.max;v+=d.axis.step)ticks.push(v);document.getElementById('axis').innerHTML=ticks.map(v=>'<span>'+((d.unit==='Vehicles'&&v)?(v/1000)+'k':v)+'</span>').join('');tl=gsap.timeline({paused:true});const T=60/122;d.series.forEach((r,i)=>{const at=i*4*T;const obj={v:0};const el=document.getElementById('v'+i);const set=()=>{el.textContent=(r.qualifier||'')+(r.value%1?obj.v.toFixed(key==='balance_sheet'?3:1):Math.round(obj.v).toLocaleString('en-US'));};set();tl.fromTo(document.querySelectorAll('.row')[i],{opacity:0,y:12},{opacity:1,y:0,duration:.4,ease:'power2.out'},at);tl.to('#b'+i,{width:(r.value/d.axis.max*100)+'%',duration:4*T,ease:'power2.out'},at);tl.to(obj,{v:r.value,duration:4*T,ease:'power2.out',onUpdate:set},at);});window.chartPreview={tl,data:d};tl.play();}document.querySelectorAll('[data-chart]').forEach(b=>b.onclick=()=>show(b.dataset.chart));document.getElementById('replay').onclick=()=>show(active);function resize(){const s=Math.min((innerWidth-32)/1080,(innerHeight-190)/1920,1);document.getElementById('canvas').style.transform='scale('+s+')';document.getElementById('wrap').style.width=(1080*s)+'px';document.getElementById('wrap').style.height=(1920*s)+'px';}window.onresize=resize;resize();show(active);</script></html>'''
(p/'chart-preview.html').write_text(source.replace('__FONT__',font).replace('__GSAP__',gsap).replace('__DATA__',json.dumps(data)))
print('Built chart-preview.html')
